// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

/**
 * @title FeeCollector
 * @dev Simple contract to collect fees for quest creation
 */
contract FeeCollector {
    address public owner;
    uint256 public feeAmount = 1 ether; // Default 1 TRUST (if 18 decimals)

    event FeePaid(address indexed payer, uint256 amount);
    event Withdrawal(address indexed to, uint256 amount);
    event FeeAmountUpdated(uint256 newFee);

    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner");
        _;
    }

    constructor() {
        owner = msg.sender;
    }

    /**
     * @dev Pay the fee. Value must be >= feeAmount.
     * Use this function to pay for quest creation or other services.
     */
    function payFee() external payable {
        require(msg.value >= feeAmount, "Insufficient fee sent");
        emit FeePaid(msg.sender, msg.value);
    }

    /**
     * @dev Update the required fee amount
     */
    function setFee(uint256 _newFee) external onlyOwner {
        feeAmount = _newFee;
        emit FeeAmountUpdated(_newFee);
    }

    /**
     * @dev Withdraw all collected funds to the specified address
     */
    function withdraw(address payable _to) external onlyOwner {
        uint256 balance = address(this).balance;
        require(balance > 0, "No funds to withdraw");
        
        (bool success, ) = _to.call{value: balance}("");
        require(success, "Transfer failed"); // Using call is safer than transfer/send
        
        emit Withdrawal(_to, balance);
    }

    /**
     * @dev Accept direct transfers (fallback)
     */
    receive() external payable {
        emit FeePaid(msg.sender, msg.value);
    }
}
